import subprocess, sys, glob, itertools, random, os
random.seed(1)
opts = {
 "currency":["USD","JPY","SEK","","XYZ"],"rounding":["up","half_even"],"round_step":["0.05","0.5","0.001"],
 "tax_rate":["0.19","0","0.2000"],"fuel_pct":["0","20"],"dim_divisor":["4000","6000"],"units":["imperial"],
 "carriers":["express,ground","courier","freight,courier"],"zone_overrides":["CH=3,US=2","bad","DE=5"],
 "rate_card":["2026"],"surcharge_remote":["9"],"surcharge_peak":["3"],"insurance_pct":["2"],"insurance_min":["10"],
 "discount_tiers":["1:10,3:20","x"],"fx_margin":["0","5"],"box_set":["eco","none"],"packing_margin_cm":["0","10"],
 "cache_enabled":["no"],"debug":["1"],"line_width":["30"],"csv_delimiter":[";"],"json_indent":["0","4"],
 "label_format":["long"],"pricing_date":["2026-12-20","2026-11-14","2027-12-30"],"saturday_delivery":["yes"],
 "ground_markup":["5"],"freight_markup":["9"],
}
shipf = sorted(glob.glob("samples/shipments-*.csv"))
def run(root, args, env=None):
    e = {k:v for k,v in os.environ.items() if not k.startswith("QUOTER_")}; e.update(env or {})
    p = subprocess.run([sys.executable,"-m","quoter",*args],cwd=root,env=e,capture_output=True,text=True)
    return (p.returncode,p.stdout,p.stderr)
bad=0;n=0
cmds=[]
for i in range(150):
    sets=[]
    for k in random.sample(list(opts), random.randint(0,5)):
        sets += ["--set", f"{k}={random.choice(opts[k])}"]
    c = random.choice([
      ["quote","--from","DE-10115","--to",random.choice(["FR-75001","US-10001","DE-18565","GB-EC1A 1BB","DE-10117"]),"--weight",random.choice(["2","0.4","35","120"]),"--dims",random.choice(["30x20x10","130x20x10","100x90x60"]),"--format",random.choice(["text","detail","csv","json","label"]),"--insure","300","--residential"],
      ["batch",random.choice(shipf),"--format",random.choice(["text","csv","json"])],
      ["zones","de"],["carriers"],["settings"]])
    cmds.append(sets+c)
for cf in glob.glob("samples/*.ini"):
    for f in shipf: cmds.append(["--config",cf,"batch",f,"--format","json"])
for a in cmds:
    n+=1
    o=run("/tmp/orig",a); w=run("/app",a)
    if o!=w:
        bad+=1; print("DIFF",a); 
        if bad<4: print(o,w,sep="\n")
print(n,"runs",bad,"diffs")
